export { COLORS } from './src/host/constants.js'

export const name = 'ds-bot'
export const inject = ['llm', 'tools', 'systemPrompt', 'sessionController', 'sessions', 'sessionTitle', 'workspaceRegistry', 'connection']

// Each module's install(rt) registers its listeners, tools, and effects, and puts on `rt`
// the functions other modules call; they call them through `rt` at run time, never during
// install. Listeners run and tools are listed in registration order, so this order holds:
// usage meters model requests after every listener that rewrites them. privacy checks a
// call before the hooks of tools do, so a closed call never reaches a card they show.
const MODULES = [diagnostics, store, models, providers, permissions, turns, steer, handoffs, requests, delivery, roster, folders, privacy, agents, prompt, timeContext, tools, chatIndex, groups, goals, approvals, resume, memory, parts, images, avatarLibrary, secrets, connectors, capabilities, learning, schedules, browser, browserPlugins, computer, usage, update, dshUpdate, thinking, feed, im, channel, officeSkills, goalSkills, localAgents]

export function apply(ctx, config = {}) {
  createRuntime(ctx, config)
}

export function createRuntime(ctx, config = {}) {
  const dshHome = folders.dshHomeOf(process.env.DSH_HOME)
  const home = config.home ?? join(dshHome, 'bot')
  const rt = {
    ctx,
    config,
    dshHome,
    home,
    statePath: join(home, 'state.json'),
    // The Bot-only tools each module defines; tools.js registers them in each
    // Bot Session's own scope, never globally (see shareBotTools).
    teamTools: [],
    defaults: {
      mainName: config.mainName ?? 'Chief',
      mainRole: config.mainRole ?? 'Chief of Staff',
    },

// How a user message reaches a Session: a Bot id, a group chat's id, or an earlier
// part of either resolves to its current part. `content` is the prompt blocks DSH
// takes (text, image, file receipts); `requestId` lands on the message's source.
async function sendUser({ sessionId: ref, content, requestId = randomUUID() }) {
  const past = rt.pastOwners.get(ref)
  const room = rt.roomOf(ref)
  const sessionId = rt.botOf(ref) ? rt.chatOf(ref)
    : room !== undefined ? rt.sessionOfRoom(room)
      : past?.roomId === undefined && past !== undefined ? rt.chatOf(past.botId)
        : past !== undefined ? rt.sessionOfRoom(rt.roomOf(past.roomId)) : ref
  await rt.ensureCapabilities(sessionId)
  await ctx.sessionController.prompt({
    requestId,
    sessionId,
    mode: 'queue',
    content,
  }, AbortSignal.timeout(30_000))
}

const onMessage = (conn) => async (msg) => {
  if (!paired(conn, msg.sender.id)) {
    if (msg.chat.kind === 'group' && !msg.mentioned) return
    if (!requested(conn, msg)) return
    await rt.save()
    await sendText(conn, msg.chat, text('requested'))
    return
  }
  conn.chats ??= {}
  if (msg.chat.kind === 'group' && !msg.mentioned) return
  if (conn.chats[msg.chat.key] === undefined) {
    conn.chats[msg.chat.key] = { kind: msg.chat.kind, title: msg.chat.title, at: Date.now() }
    await rt.save()
  }

  const sessionId = target.botId ?? target.roomId
  const content = []
  if (body !== '') content.push({ type: 'text', text: body })
  for (const image of msg.images ?? []) content.push({ type: 'image', mediaType: image.mediaType, data: image.data })
  const env = await envFor(conn)
  for (const file of msg.files ?? []) {
    try {
      const receiptId = await env.uploadFile(rt.botOf(sessionId) ? rt.chatOf(sessionId) : sessionId, file)
      content.push({ type: 'file', receiptId })
    } catch {
      await sendText(conn, msg.chat, text('noFile'))
    }
  }
  if (content.length === 0) return
  await rt.sendUser({ sessionId, content, requestId: `im:${conn.platform}:${randomUUID()}` })
}

// A group chat, kept in the group's memory and read once for all its members.
// `seen.room` holds the lines that left the log while the review waited, so who
// has joined or left since changes nothing. A deleted group's memory is archived
// with it, so nothing more is kept of it.
async function reviewGroup(seen) {
  const live = rt.roomOf(seen.roomId)
  const keeper = live === undefined ? undefined : keeperOf(live)
  if (keeper === undefined) return
  const room = joinLogs(seen.room, live)
  const since = cursorsNow()[seen.key]
  const members = live.members.map(id => rt.botOf(id)).filter(Boolean).map(bot => `${bot.name}${live.admin === bot.id ? ' (admin)' : ''}`)
  await reviewBatch({
    key: seen.key, since, batch: groupBatch(room, since),
    keeper, name: `group "${live.name}"`, home: groupScope(live.id), teamWrites: () => false, group: true,
    who: `The group chat: "${live.name}", with the user and ${members.join(', ')}.`,
    tag: { sessionId: live.id, kind: 'memory' },
    alive: () => rt.botOf(keeper.id) !== undefined && rt.roomOf(live.id)?.members.includes(keeper.id) === true,
    next: () => queueReview({ ...seen, room }),

// Only the user's words are kept, so lines without any need no model call.
if (read.some(line => line.who === 'user')) {
  const { homeFiles, teamFiles } = await settled(() => ({ homeFiles: loadScope(home), teamFiles: loadScope(TEAM) }))
  const said = read.filter(line => line.who === 'user').map(line => line.text).join('\n')
  const tagged = group ? 'group' : 'own'
  const { numbered, left } = reviewEntries(homeFiles, teamFiles, REVIEW_MEMORY_MAX, said, tagged)
  const sizes = { home: homeFiles[0].content.length, team: teamFiles[0].content.length }
  const earlier = batch.earlier.map(line => reviewLine(line.who, line.text, keeper))
  const language = writtenIn(read.filter(line => line.who === 'user').map(line => line.text.replace(/^User: /, '')), languageNow())
  const reply = await botShot(keeper, reviewSystem({ teamWrites: teamWrites(), group }), reviewRequest({ who, tag: tagged, numbered, left, sizes, where: batch.where, earlier, fresh: fresh.texts, more, language }), tag)

// Group chat settings. The user and every Main Bot may change any group; a group's
// admin may change its own group but not delete it. Only a member can be admin.

const roomBusy = id => [...rt.roomProgress.values()].some(round => round.roomId === id)
const autoRoomName = members => ['You', ...members.map(id => rt.botOf(id)?.name).filter(Boolean)].join(', ')

// The loop's runtime-context user messages are context, not input: they
// fold into the next prompt or steer, never start a prompt on their own.
const contextText = delta
  .filter(message => message.role === 'user' && message.source?.kind === 'runtime-context')
  .map(message => textOf(message.content)).filter(text => text !== '').join('\n')
const users = delta.filter(message => message.role === 'user' && message.source?.kind !== 'runtime-context')

const adapter = new LocalAgentAdapter({
  rt,
  customAgents,
  findExecutable,
  spawnEngine,
  record: sessionId => store().sessions[sessionId],
  saveRecord: (sessionId, record) => {
    store().sessions[sessionId] = record
    void rt.save().catch(() => {})
  },
  presetFor: (sessionId) => {
    const bot = rt.botOf(rt.selfOf(sessionId))
    const room = rt.roomOf(rt.groupOwners.get(sessionId)?.roomId)
    return room?.permission ?? bot?.permission ?? 'workspace-write'
  },
  cwdFor: async (sessionId) => {
    try {
      const agent = await rt.resolveAgent(sessionId)
      return agent.session.header?.cwd ?? rt.workDirOf?.({ botId: rt.selfOf(sessionId), roomId: rt.groupOwners.get(sessionId)?.roomId }) ?? rt.teamFolder?.() ?? tmpdir()
    } catch {
      return rt.teamFolder?.() ?? tmpdir()
    }
  },
  probeCwd: () => mkdtempSync(join(tmpdir(), 'dsb-probe-')),
  toolsFor: (options) => {
    // Only DS Bot's own team tools cross the bridge; the CLI keeps its own.
    const names = new Set([...rt.teamTools.map(def => def.name), 'approve_agent_action'])
    return (options.tools ?? []).filter(tool => names.has(tool.name))

// App and foreground leases: in-memory, process-local. A lease says "this Bot is
// operating that app" (or the foreground) so another Bot's call is refused instead
// of two Bots typing into the same window. Leases end with the holder's turn, after
// a short idle, on stop and on takeover; observe calls never need one.
const IDLE_MS = 60_000

// An archive from DSH's own Session list while the team runs: DSH asks for the
// Session's activity (plain archive) or stops it (stopActivity) inside the archive,
// so an unarchive started here queues behind that archive and undoes it. The team's
// own archives drop the Session from its owner first.
const keepCurrent = ({ sessionId }) => {
  if (readOnly() || !(rt.isBotSession(sessionId) || rt.roomOwners.has(sessionId))) return
  void ctx.workspaceRegistry.unarchiveSession(sessionId)
    .catch(error => rt.warn('ds-bot: current Session %s is archived in DSH and could not be taken out: %s', sessionId, error))
}
ctx.on('workspace/session-stop', keepCurrent)
ctx.on('workspace/session-activity', (request, next) => {
  keepCurrent(request)
  return next()
})
